// =====================================================================
// SONDA: descobre em que campo da Omie o RF esta gravado.
// Mode: Run Once for All Items · CUSTO: 2 chamadas de API. So' LEITURA.
//
// Como funciona: chama ObterNFSe (pela nota) e ConsultarOS (pela OS), e
// varre as duas respostas inteiras procurando o PADRAO de um RF da Vale
// (10 digitos comecando em 62, ex. 6203185520). Devolve o CAMINHO no JSON
// onde encontrou -- ou seja, ela se autodescobre, ninguem precisa saber o
// nome do campo antes.
// =====================================================================

const cfg       = $input.first().json;
const appKey    = cfg.OMIE_APP_KEY;
const appSecret = cfg.OMIE_APP_SECRET;
const nIdNf     = Number(cfg.NIDNF);
const cNumOS    = String(cfg.CNUMOS || '').trim();

if (!appKey || !appSecret || String(appKey).indexOf('COLE_') === 0) {
  throw new Error('Preencha OMIE_APP_KEY e OMIE_APP_SECRET no no Config.');
}

// Um RF da Vale: comeca em 62 e tem 10 digitos (o normal).
// Aceita 8 a 12 digitos depois do "62" porque o banco tem casos de 11 e 12
// digitos (conferido em 10/08/2026: 799 RFs com 10, 2 com 11, 4 com 12 --
// os maiores sao artefato de teste, alguem acrescentou digito para o RF
// "virar novo"). Um padrao de 10 exatos deixaria esses de fora.
const PADRAO_RF = /\b62\d{8,12}\b/g;

// Nomes de campo que costumam guardar texto livre -- listados mesmo sem
// casar o padrao, porque o RF pode estar formatado de outro jeito.
const NOMES_TEXTO = /obs|hist|anot|inform|complement|descr|coment/i;

const chamar = (opcoes) => this.helpers.httpRequest(opcoes);

function motivoOmie(e) {
  const cands = [
    e && e.response && e.response.data,
    e && e.response && e.response.body,
    e && e.cause && e.cause.response && e.cause.response.data,
    e && e.error, e && e.description,
  ];
  for (const c of cands) {
    if (!c) continue;
    let o = c;
    if (typeof o === 'string') {
      try { o = JSON.parse(o); } catch (_) { return o.slice(0, 300); }
    }
    if (o && (o.faultstring || o.faultcode)) {
      return String(o.faultcode || '') + ' ' + String(o.faultstring || '');
    }
    try { return JSON.stringify(o).slice(0, 300); } catch (_) { /* segue */ }
  }
  return e && e.message ? String(e.message) : 'sem detalhe';
}

async function tentar(nome, url, corpo) {
  try {
    const r = await chamar({
      method: 'POST', url: url,
      headers: { 'Content-Type': 'application/json' },
      body: corpo, json: true,
    });
    return { nome: nome, ok: true, resposta: r };
  } catch (e) {
    return { nome: nome, ok: false, erro: motivoOmie(e) };
  }
}

// varredura recursiva: registra caminho + valor onde o padrao casa
function varrer(no, caminho, achados, textos) {
  if (no === null || no === undefined) return;

  if (typeof no === 'string' || typeof no === 'number') {
    const s = String(no);
    const casou = s.match(PADRAO_RF);
    if (casou) {
      achados.push({
        caminho: caminho,
        valor: s.length > 300 ? s.slice(0, 300) + '...' : s,
        rfs: [...new Set(casou)],
      });
    }
    // campo de texto livre com conteudo: registra para inspecao manual
    const ultimo = caminho.split('.').pop() || '';
    if (NOMES_TEXTO.test(ultimo) && s.trim()) {
      textos.push({ caminho: caminho, valor: s.length > 300 ? s.slice(0, 300) + '...' : s });
    }
    return;
  }

  if (Array.isArray(no)) {
    for (let i = 0; i < no.length; i++) varrer(no[i], caminho + '[' + i + ']', achados, textos);
    return;
  }

  if (typeof no === 'object') {
    for (const k of Object.keys(no)) {
      varrer(no[k], caminho ? caminho + '.' + k : k, achados, textos);
    }
  }
}

const chamadas = [];

// 1) a nota (o fluxo diario ja' usa esta chamada para pegar cNumOs/xml/pdf)
chamadas.push(await tentar('ObterNFSe', 'https://app.omie.com.br/api/v1/servicos/osdocs/', {
  call: 'ObterNFSe', app_key: appKey, app_secret: appSecret,
  param: [{ nIdNf: nIdNf }],
}));

await new Promise((s) => setTimeout(s, 500));

// 2) a Ordem de Servico (suspeita principal: faturamento e' POR OS)
if (cNumOS) {
  chamadas.push(await tentar('ConsultarOS', 'https://app.omie.com.br/api/v1/servicos/os/', {
    call: 'ConsultarOS', app_key: appKey, app_secret: appSecret,
    param: [{ cNumOS: cNumOS }],
  }));
}

const saida = [];
for (const c of chamadas) {
  if (!c.ok) {
    saida.push({ chamada: c.nome, ok: false, erro: c.erro });
    continue;
  }
  const achados = [];
  const textos = [];
  varrer(c.resposta, '', achados, textos);

  saida.push({
    chamada: c.nome,
    ok: true,
    ACHOU_RF: achados.length > 0,
    onde_o_rf_esta: achados,
    campos_de_texto_livre: textos,
    campos_no_topo: Object.keys(c.resposta || {}),
    // resposta crua truncada, para eu ler a estrutura
    resposta_crua: JSON.stringify(c.resposta).slice(0, 6000),
  });
}

const achouAlgum = saida.some(function (s) { return s.ACHOU_RF; });
console.log('sonda concluida. Achou RF? ' + achouAlgum);

return [{
  json: {
    nIdNf: nIdNf,
    cNumOS: cNumOS,
    padrao_procurado: String(PADRAO_RF),
    ACHOU_RF_EM_ALGUMA: achouAlgum,
    resultado: saida,
  },
}];
